// ══════════════════════════════════════════════════
//  Node 2: Verify Invitation Code
// ══════════════════════════════════════════════════

const body = $input.first().json.body || $input.first().json;
const submittedCode = (body.verificationCode || '').trim().toUpperCase();

let expectedCode = 'SCVA-2026';
try {
  const varCode = $vars.SCVA_VERIFICATION_CODE;
  if (varCode && String(varCode).trim()) {
    expectedCode = String(varCode).trim().toUpperCase();
  }
} catch (e) {}

if (!submittedCode) {
  throw new Error('MISSING_CODE: رمز التحقق مطلوب');
}

if (submittedCode !== expectedCode) {
  throw new Error('INVALID_VERIFICATION_CODE: رمز التحقق غير صحيح');
}

return [{ json: body }];

// ══════════════════════════════════════════════════
//  Node 3: Format & Validate Data
// ══════════════════════════════════════════════════

const d = $input.first().json;

const required = ['firstName', 'lastName', 'fullName', 'englishName'];
for (const f of required) {
  if (!d[f] || !String(d[f]).trim()) {
    throw new Error(`MISSING_REQUIRED: الحقل المطلوب غير موجود: ${f}`);
  }
}

const clean = (v) => (v ? String(v).trim() : '');

const language = clean(d.language) || 'ar';
const submittedAt = d.submittedAt || new Date().toISOString();

const genderMap = {
  ar: { male: 'ذكر', female: 'أنثى' },
  en: { male: 'Male', female: 'Female' },
};
const specialtyMap = {
  ar: { cardiology: 'قلبية داخلية', cardiac_surgery: 'جراحة قلب' },
  en: { cardiology: 'Cardiology', cardiac_surgery: 'Cardiac Surgery' },
};
const membershipMap = {
  ar: { original: 'عضو أصيل', associate: 'عضو مشارك' },
  en: { original: 'Original Member', associate: 'Associate Member' },
};

const gender = genderMap[language]?.[d.gender] || clean(d.gender);
const specialty = specialtyMap[language]?.[d.specialty] || clean(d.specialty);
const membershipType = membershipMap[language]?.[d.membershipType] || clean(d.membershipType);

return [{
  json: {
    language,
    verificationCode: clean(d.verificationCode),
    firstName:    clean(d.firstName),
    lastName:     clean(d.lastName),
    fullName:     clean(d.fullName),
    fatherName:   clean(d.fatherName),
    englishName:  clean(d.englishName),
    birthDate:    clean(d.birthDate),
    gender:       gender,
    genderRaw:    clean(d.gender),
    specialty:    specialty,
    specialtyRaw: clean(d.specialty),
    membershipType: membershipType,
    membershipTypeRaw: clean(d.membershipType),
    email:        clean(d.email),
    phone:        clean(d.phone),
    city:         clean(d.city),
    workAddress:  clean(d.workAddress),
    joinDate:     clean(d.joinDate),
    escId:        clean(d.escId),
    submittedAt,
  }
}];

// Build Email HTML v3.0 — Gmail-safe inline styles
const d = $input.first().json;
const v = (val) => (val && String(val).trim()) ? String(val).trim() : '—';
const isAr = d.language !== 'en';

function fmtDate(iso) {
  try {
    const dt = new Date(iso);
    if (isNaN(dt.getTime())) return iso || '—';
    const pad = n => String(n).padStart(2, '0');
    return pad(dt.getDate()) + '/' + pad(dt.getMonth() + 1) + '/' + dt.getFullYear()
         + '  ' + pad(dt.getHours()) + ':' + pad(dt.getMinutes());
  } catch (e) { return iso || '—'; }
}

const submittedFmt = fmtDate(d.submittedAt || new Date().toISOString());
const aiAnalysis   = d.aiAnalysis || '';
const aiWelcome    = d.aiWelcome  || '';

// ── AI block (admin) ──────────────────────────────────────────────────
const aiAdminBlock = aiAnalysis
  ? '<tr><td colspan="2" style="background:#fefce8;border:1px solid #fde047;border-radius:6px;padding:12px 14px;font-size:13px;color:#713f12;line-height:1.8">'
    + '<strong style="display:block;font-size:11px;color:#a16207;margin-bottom:4px">🤖 تحليل الذكاء الاصطناعي</strong>'
    + aiAnalysis + '</td></tr>'
  : '';

// ── Helper: table row ─────────────────────────────────────────────────
const row = (label, value, alt) =>
  '<tr style="background:' + (alt ? '#f8fafc' : '#fff') + '">'
  + '<td style="padding:8px 12px;font-size:13px;color:#64748b;font-weight:600;width:38%;border-bottom:1px solid #f1f5f9;white-space:nowrap">' + label + '</td>'
  + '<td style="padding:8px 12px;font-size:13px;color:#1e293b;border-bottom:1px solid #f1f5f9">' + value + '</td>'
  + '</tr>';

const sectionHeader = (title) =>
  '<tr><td colspan="2" style="background:#e0f2fe;padding:8px 12px;font-size:11px;font-weight:700;color:#0369a1;letter-spacing:.5px;text-transform:uppercase">' + title + '</td></tr>';

// ═══════════════════════════════════════════════════════════════════════
// ADMIN EMAIL
// ═══════════════════════════════════════════════════════════════════════
const adminHtml = '<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head>'
  + '<body style="font-family:Arial,Helvetica,sans-serif;background:#f0f4f8;margin:0;padding:20px;direction:rtl">'
  + '<div style="max-width:620px;margin:0 auto;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 20px rgba(0,0,0,0.1)">'
  // header
  + '<div style="background:#1a3a5c;color:#ffffff;padding:28px;text-align:center">'
  + '<div style="font-size:36px;margin-bottom:8px">🔔</div>'
  + '<h1 style="margin:0 0 6px;font-size:18px;color:#ffffff;font-weight:700">إشعار تسجيل عضو جديد</h1>'
  + '<p style="margin:0;font-size:12px;color:#94c5e8">الرابطة السورية لأمراض وجراحة القلب</p>'
  + '<span style="display:inline-block;background:rgba(255,255,255,0.15);border:1px solid rgba(255,255,255,0.35);border-radius:20px;padding:3px 14px;font-size:11px;color:#fff;margin-top:8px">' + (isAr ? 'نموذج عربي' : 'English Form') + '</span>'
  + '</div>'
  // body
  + '<div style="padding:24px 28px">'
  + '<div style="background:#f0fdf4;border:1px solid #86efac;border-radius:8px;padding:12px 14px;margin-bottom:16px;font-size:13px;color:#166534">✅ تم استلام طلب عضوية جديد بنجاح عبر النموذج الإلكتروني.</div>'
  + '<table style="width:100%;border-collapse:collapse;margin-bottom:20px">'
  + aiAdminBlock
  + sectionHeader('البيانات الشخصية')
  + row('الاسم الكامل (عربي)', v(d.fullName), false)
  + row('الاسم الكامل (إنجليزي)', v(d.englishName), true)
  + row('اسم الأب', v(d.fatherName), false)
  + row('تاريخ الميلاد', v(d.birthDate), true)
  + row('الجنس', v(d.gender), false)
  + sectionHeader('البيانات المهنية')
  + row('التخصص', v(d.specialty), false)
  + row('نوع العضوية', v(d.membershipType), true)
  + row('تاريخ الانضمام', v(d.joinDate), false)
  + row('ESC ID', v(d.escId), true)
  + sectionHeader('بيانات التواصل')
  + row('البريد الإلكتروني', v(d.email), false)
  + row('رقم الهاتف', v(d.phone), true)
  + row('المدينة', v(d.city), false)
  + row('عنوان العمل', v(d.workAddress), true)
  + sectionHeader('معلومات الطلب')
  + row('لغة النموذج', isAr ? 'العربية' : 'English', false)
  + row('وقت الإرسال', submittedFmt, true)
  + '</table>'
  + '</div>'
  // footer
  + '<div style="background:#f8fafc;padding:16px 28px;text-align:center;border-top:1px solid #e2e8f0">'
  + '<div style="font-size:13px;font-weight:700;color:#0f172a">الرابطة السورية لأمراض وجراحة القلب</div>'
  + '<div style="font-size:11px;color:#94a3b8;margin-top:3px">Syrian Cardiovascular Association — SCVA</div>'
  + '</div>'
  + '</div></body></html>';

// ═══════════════════════════════════════════════════════════════════════
// MEMBER CONFIRMATION EMAIL
// ═══════════════════════════════════════════════════════════════════════
const dir     = isAr ? 'rtl' : 'ltr';
const lang    = d.language || 'ar';
const nameVal = isAr ? v(d.fullName) : v(d.englishName);
const greeting = isAr ? ('عزيزي/عزيزتي الدكتور/ة ' + v(d.fullName)) : ('Dear Dr. ' + v(d.englishName));
const titleTxt = isAr ? 'تم استلام طلب العضوية' : 'Membership Application Received';
const orgName  = isAr ? 'الرابطة السورية لأمراض وجراحة القلب' : 'Syrian Cardiovascular Association — SCVA';
const defaultMsg = isAr
  ? 'يسعدنا إخبارك بأنه تم استلام طلب انضمامك بنجاح. سيقوم فريقنا المختص بمراجعة طلبك والتواصل معك قريباً.'
  : 'We are pleased to confirm that your membership application has been received. Our team will review it and contact you soon.';

const aiWelcomeBlock = aiWelcome
  ? '<div style="background:#f0fdf4;border:1px solid #86efac;border-radius:8px;padding:12px 14px;margin-bottom:16px;font-size:13px;color:#166534;line-height:1.8">' + aiWelcome + '</div>'
  : '';

const stepsTitle = isAr ? 'الخطوات القادمة' : 'Next Steps';
const steps = isAr
  ? ['مراجعة طلبك من قِبل لجنة القبول', 'التواصل معك للتحقق من المعلومات إذا لزم', 'إشعارك بقرار القبول النهائي']
  : ['Review by the admission committee', 'Contact you to verify information if needed', 'Notify you of the final admission decision'];
const stepsHtml = steps.map((s, i) => '<li style="font-size:13px;color:#374151;margin-bottom:6px;line-height:1.6">' + s + '</li>').join('');

const memberHtml = '<!DOCTYPE html><html dir="' + dir + '" lang="' + lang + '"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head>'
  + '<body style="font-family:Arial,Helvetica,sans-serif;background:#f0f4f8;margin:0;padding:20px">'
  + '<div style="max-width:620px;margin:0 auto;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 20px rgba(0,0,0,0.1)">'
  // header
  + '<div style="background:#1a3a5c;color:#ffffff;padding:28px;text-align:center">'
  + '<div style="font-size:36px;margin-bottom:8px">✅</div>'
  + '<h1 style="margin:0 0 6px;font-size:18px;color:#ffffff;font-weight:700">' + titleTxt + '</h1>'
  + '<p style="margin:0;font-size:12px;color:#94c5e8">' + orgName + '</p>'
  + '</div>'
  // body
  + '<div style="padding:24px 28px">'
  + '<p style="font-size:15px;font-weight:600;color:#0f172a;margin:0 0 14px">' + greeting + '،</p>'
  + aiWelcomeBlock
  + '<p style="font-size:13px;color:#475569;line-height:1.85;margin:0 0 20px">' + defaultMsg + '</p>'
  // summary table
  + '<div style="font-size:11px;font-weight:700;color:#0369a1;background:#e0f2fe;padding:8px 12px;margin-bottom:0;border-radius:6px 6px 0 0">'
  + (isAr ? 'ملخص طلبك' : 'Application Summary') + '</div>'
  + '<table style="width:100%;border-collapse:collapse;margin-bottom:20px;border:1px solid #e2e8f0;border-top:0">'
  + row(isAr ? 'الاسم' : 'Name', nameVal, false)
  + row(isAr ? 'البريد الإلكتروني' : 'Email', v(d.email), true)
  + row(isAr ? 'نوع العضوية' : 'Membership', v(d.membershipType), false)
  + row(isAr ? 'وقت الإرسال' : 'Submitted', submittedFmt, true)
  + '</table>'
  // steps
  + '<div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:16px 18px;margin-bottom:20px">'
  + '<h4 style="margin:0 0 10px;font-size:13px;font-weight:700;color:#1d4ed8">' + stepsTitle + '</h4>'
  + '<ol style="margin:0;padding-inline-start:20px">' + stepsHtml + '</ol>'
  + '</div>'
  + '</div>'
  // footer
  + '<div style="background:#f8fafc;padding:16px 28px;text-align:center;border-top:1px solid #e2e8f0">'
  + '<div style="font-size:13px;font-weight:700;color:#0f172a">الرابطة السورية لأمراض وجراحة القلب</div>'
  + '<div style="font-size:11px;color:#94a3b8;margin-top:3px">Syrian Cardiovascular Association — SCVA</div>'
  + '</div>'
  + '</div></body></html>';

// ── Subjects ──────────────────────────────────────────────────────────
const adminSubject = 'عضو جديد: '
  + (v(d.fullName) !== '—' ? v(d.fullName) : v(d.englishName))
  + ' | الرابطة السورية لأمراض وجراحة القلب';

const memberSubject = isAr
  ? 'تم استلام طلب انضمامك | الرابطة السورية لأمراض وجراحة القلب'
  : 'Your Membership Application Received | SCVA';

return [{
  json: {
    language: d.language, verificationCode: d.verificationCode,
    firstName: d.firstName, lastName: d.lastName, fullName: d.fullName,
    fatherName: d.fatherName, englishName: d.englishName, birthDate: d.birthDate,
    gender: d.gender, genderRaw: d.genderRaw, specialty: d.specialty,
    specialtyRaw: d.specialtyRaw, membershipType: d.membershipType,
    membershipTypeRaw: d.membershipTypeRaw, email: d.email, phone: d.phone,
    city: d.city, workAddress: d.workAddress, joinDate: d.joinDate,
    escId: d.escId, submittedAt: d.submittedAt,
    adminHtml,
    memberHtml,
    adminSubject,
    memberSubject,
    memberEmail: d.email || '',
  }
}];

// AI Analysis Node v2.5 — Gemini multi-model fallback
const d = $input.first().json;
let aiAnalysis = '';
let aiWelcome  = '';

const AI_PROVIDER = '__SCVA_AI_PROVIDER__';
const AI_API_KEY  = '__SCVA_AI_KEY__';

try {
  const hasKey = AI_API_KEY && AI_API_KEY !== '__SCVA_AI_KEY__' && AI_API_KEY.length > 10;
  const canFetch = typeof fetch === 'function';

  if (hasKey && canFetch) {

    const callAI = async (prompt, maxTokens) => {
      if (AI_PROVIDER === 'gemini') {
        const models = [
          'gemini-2.5-flash-preview-04-17',
          'gemini-2.5-flash',
          'gemini-2.0-flash-001',
          'gemini-1.5-flash',
        ];
        for (const model of models) {
          const url = 'https://generativelanguage.googleapis.com/v1beta/models/' + model + ':generateContent?key=' + AI_API_KEY;
          const resp = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ contents: [{ parts: [{ text: prompt }] }] })
          });
          if (resp.ok) {
            const json = await resp.json();
            return json.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || '';
          }
          const errData = await resp.json().catch(() => ({}));
          const errMsg = errData?.error?.message || '';
          const notAvailable = resp.status === 404 || /no longer available|not found|not supported/i.test(errMsg);
          if (!notAvailable) break;
        }
        return '';
      } else {
        const resp = await fetch('https://api.openai.com/v1/chat/completions', {
          method: 'POST',
          headers: {
            'Authorization': 'Bearer ' + AI_API_KEY,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            model: 'gpt-4o-mini',
            messages: [{ role: 'user', content: prompt }],
            max_tokens: maxTokens,
            temperature: 0.7
          })
        });
        const json = await resp.json();
        return json.choices?.[0]?.message?.content?.trim() || '';
      }
    };

    const adminPrompt =
      'انت مساعد اداري للرابطة السورية لامراض وجراحة القلب (SCVA).\n' +
      'تلقت الرابطة طلب عضوية جديدة بالبيانات التالية:\n' +
      '- الاسم: ' + (d.fullName || '-') + ' (' + (d.englishName || '-') + ')\n' +
      '- التخصص: ' + (d.specialty || 'غير محدد') + '\n' +
      '- نوع العضوية: ' + (d.membershipType || 'غير محدد') + '\n' +
      '- المدينة: ' + (d.city || 'غير محددة') + '\n' +
      '- ESC ID: ' + (d.escId || 'غير موجود') + '\n' +
      '- بريد الكتروني: ' + (d.email ? 'موجود' : 'غير موجود') + '\n' +
      '- هاتف: ' + (d.phone ? 'موجود' : 'غير موجود') + '\n\n' +
      'اكتب فقرة احترافية موجزة (3-4 جمل) تتضمن تقييم الطلب واي بيانات ناقصة وتوصية بالاجراء القادم. اكتب مباشرة دون عنوان.';

    aiAnalysis = await callAI(adminPrompt, 300);

    const isAr = d.language !== 'en';
    const memberPrompt = isAr
      ? 'اكتب جملتين او ثلاث جمل ترحيبية دافئة واحترافية للدكتور ' + (d.fullName || '') +
        ' المتقدم لعضوية "' + (d.membershipType || 'العضوية') + '" في الرابطة السورية لامراض وجراحة القلب.' +
        ' اشكره على تقديم طلبه واذكر ان المراجعة ستستغرق وقتا قصيرا.'
      : 'Write 2-3 warm and professional welcome sentences to Dr. ' + (d.englishName || '') +
        ' who applied for "' + (d.membershipType || 'membership') + '" at the Syrian Cardiovascular Association (SCVA).' +
        ' Thank them and mention their application is under review.';

    aiWelcome = await callAI(memberPrompt, 150);
  }
} catch (_) {
  aiAnalysis = '';
  aiWelcome  = '';
}

return [{ json: { ...d, aiAnalysis, aiWelcome } }];
